var Keyword = class {
	constructor(name) {
		this.name = "";
		this.toString = () => `:${this.name}`;
		this.name = name;
	}
};
var File = class {
	constructor(path) {
		this.path = "";
		this.toString = () => `(clojure.java.io/file "${this.path}")`;
		this.path = path;
	}
};
const jsType = (input) => {
	if (input === void 0) return null;
	if (input === null) return "null";
	return input.constructor.name.toLowerCase();
};
const objEmpty = (input) => {
	if (input === void 0) return true;
	else if (jsType(input) === "object") return Object.keys(input).length === 0;
	return false;
};
const filterEmpty = (input) => {
	Object.keys(input).filter((x) => objEmpty(input[x])).forEach((x) => {
		delete input[x];
	});
	return input;
};
const padBlock = (padSize, input) => {
	const padding = " ".repeat(padSize);
	return input.replace(/\n/g, `\n${padding}`);
};
const jsToEdn = (js) => {
	switch (jsType(js)) {
		case "string": return `"${js.replace(/"/g, "\\\"")}"`;
		case "file": return js.toString();
		case "keyword": return js.toString();
		case "null": return "nil";
		case "regexp": return `#"${js.source}"`;
		case "object": {
			const obj = Object.keys(js).reduce((accumulator, key) => {
				return `${accumulator}:${key} ${padBlock(key.length + 2, jsToEdn(js[key]))}\n `;
			}, "").trim();
			return `{${padBlock(1, obj)}}`;
		}
		case "array": {
			const arr = js.reduce((accumulator, value) => `${accumulator} ${jsToEdn(value)}`, "").trim();
			return `[${padBlock(1, arr)}]`;
		}
		default: return js.toString();
	}
};
